import{_ as t,c as o,o as r,ae as a}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse(`{"title":"Export Refunds","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-refunds-export","title":"Export Refunds (CSV)","description":"Download the refunds datagrid as a CSV file — the same data the admin Refunds \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/refunds/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output refunds.csv\\n","response":"# Binary response: a text/csv attachment is written to refunds.csv\\n# (Content-Disposition: attachment; filename=\\"refunds.csv\\"). Sample contents:\\n\\nID,\\"Order ID\\",\\"Refunded Amount\\",\\"Billed To\\",\\"Refund Date\\"\\n1,105,\\"$4,233.00\\",\\"John Doe\\",\\"2025-04-16 22:13:30\\"\\n"},{"id":"admin-refunds-export-xlsx","title":"Export Refunds (XLSX)","description":"Download the refunds datagrid as an XLSX file — the same data the admin Refunds \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/refunds/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output refunds.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"refunds.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-refunds-export-xls","title":"Export Refunds (XLS)","description":"Download the refunds datagrid as an XLS file — the same data the admin Refunds \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/refunds/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output refunds.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"refunds.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/refunds/export.md","filePath":"api/rest-api/admin/sales/refunds/export.md"}`),n={name:"api/rest-api/admin/sales/refunds/export.md"};function d(s,e,i,c,p,l){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="export-refunds" tabindex="-1">Export Refunds <a class="header-anchor" href="#export-refunds" aria-label="Permalink to &quot;Export Refunds&quot;">​</a></h1><p>Downloads the refunds datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Sales → Refunds</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON. Requires the <code>sales.refunds.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/refunds/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the five datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Refund id.</td></tr><tr><td><code>Order ID</code></td><td>The parent order&#39;s number.</td></tr><tr><td><code>Refunded Amount</code></td><td>The total amount refunded, in the store&#39;s base currency, formatted (e.g. <code>$4,233.00</code>) — this is the refund&#39;s grand total, not just the line-items subtotal.</td></tr><tr><td><code>Billed To</code></td><td>Name on the order&#39;s billing address.</td></tr><tr><td><code>Refund Date</code></td><td>When the refund was created.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>; any other value returns <code>422</code>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/refunds/list.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>id</code>, <code>order_id</code>, <code>state</code>, <code>base_grand_total_from</code> / <code>_to</code>, <code>billed_to</code>, <code>created_at_from</code> / <code>_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.refunds.view</code></p>',12)]))}const m=t(n,[["render",d]]);export{h as __pageData,m as default};
